function terrainScene(cell){let sc=new T.Scene();sc.background=new T.Color('#a9b8ac');sc.fog=new T.Fog('#a9b8ac',100,210);sc.add(new T.HemisphereLight(0xe6eedb,0x536246,1.6));let sun=new T.DirectionalLight(0xffe1b0,2.5);sun.position.set(-35,65,30);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-80,right:80,top:70,bottom:-70,near:1,far:160});sun.shadow.bias=-.0003;sun.shadow.normalBias=.05;sun.shadow.radius=3;sc.add(sun);const geo=new T.PlaneGeometry(150,130,150,130);geo.rotateX(-Math.PI/2);const pos=geo.attributes.position,colors=[];for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),h=localHeight(cell,x,z,s.world.seed);pos.setY(i,h);const n=smooth(x/9+cell.c*8,z/9+cell.r*8),base=new T.Color(h<.4?'#c8ba91':cell.biome==='hills'?'#989375':cell.biome==='forest'?'#738c54':'#a4ac77');base.multiplyScalar(.85+n*.22);colors.push(base.r,base.g,base.b)}geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const terrainMat=new T.MeshStandardMaterial({vertexColors:true,map:groundTexture,roughness:1});terrainMat.userData.local=true;const mesh=new T.Mesh(geo,terrainMat);mesh.receiveShadow=true;sc.add(mesh);const waterMaterial=new T.MeshStandardMaterial({color:'#488b9b',roughness:.28,metalness:.2,transparent:true,opacity:.88});waterMaterial.userData.local=true;const water=new T.Mesh(new T.PlaneGeometry(150,130),waterMaterial);water.rotation.x=-Math.PI/2;water.position.y=0;sc.add(water);const world=tileWorld(cell),fort=s.campaign.battle?.fortress;if(fort)clearFootprint(world,{...fort,navWidth:8.2,navDepth:5});for(const resource of world.resources)resourceMesh(resource,sc,(x,z)=>localHeight(cell,x,z,s.world.seed));const trails=trailSurface(sc,world,(x,z)=>localHeight(cell,x,z,s.world.seed));trails.update();return {sc,mesh,trails}}
