function beginBattle(cell){s.campaign.battle=createBattle(cell,s.units);const present=s.campaign.armies.filter(a=>a.c===cell.c&&a.r===cell.r&&hasArmy(a.team)).map(a=>a.team);s.campaign.battle.squads=s.campaign.battle.squads.filter(u=>present.includes(u.team));const city=cities.find(c=>ready(s,c.team,'hall')&&c.c===cell.c&&c.r===cell.r&&present.some(team=>team!==s.campaign.cityOwners[c.team]));if(city)s.campaign.battle.fortress={cityTeam:city.team,team:s.campaign.cityOwners[city.team],hp:s.campaign.cityHealth[city.team],maxHp:600,x:48,z:8,cool:0};const saved=s.campaign.deployments?.[cell.c+':'+cell.r];if(saved)for(const squad of s.campaign.battle.squads){const p=saved[squad.source];if(p){squad.x=p.x;squad.z=p.z;squad.heading=p.heading;squad.target=null}}showLocal(cell,true);say(s.campaign.battle.fortress?'Linna piiramine! Vali „Ründa“, et vallutada kindlus.':'Armeed kohtusid! Vali üksus ja anna liikumiskäsk või vali „Ründa“.');saveCampaign()}
