function localOrder(p){const b=s.campaign.battle;if(b?.result)return;const squads=b?b.squads:inspectionSquads;const own=squads.filter(u=>u.team===0&&u.hp>0&&dist(u,p)<3.5).sort((a,b)=>dist(a,p)-dist(b,p))[0];if(own){battleSelected=own;say(stats[own.kind].name+' valitud. Puuduta sihtkohta.');return 'selected'}if(battleSelected?.team===0&&battleSelected.hp>0){battleSelected.advance=!!(b?.fortress&&dist(p,b.fortress)<9);if(localHeight(localCell,p.x,p.z,s.world.seed)<=.18){say('See koht on vee all. Vali kuiv maa.');return 'water'}battleSelected.target={x:Math.max(-69,Math.min(69,p.x)),z:Math.max(-59,Math.min(59,p.z))};saveCampaign();say('Liikumiskäsk antud.');return 'ordered'}say('Vali esmalt oma sinine väeüksus.');return 'none'}
